{
  "name": "e-Tuntutan WP1.4",
  "description": "Sistem Pengurusan Tuntutan Elaun Perjalanan Dalam Negeri (WP1.4) untuk penjawat awam Malaysia.",
  "requestFramePermissions": []
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface OfficerInfo {
  nama: string;
  ic: string;
  jawatan: string;
  gred: string;
  akaunBank: string;
  namaBank: string;
  telefon: string;
  gaji: number;
  elaun: number;
  kenderaanJenis: 'Kereta' | 'Motosikal';
  kenderaanModel: string;
  noPendaftaran: string;
  alamatPejabat: string;
  alamatRumah: string;
}

export interface JourneyLog {
  id: string;
  tarikh: string;
  waktuBertolak: string;
  waktuSampai: string;
  butiran: string;
  jarak: number;
}

export interface PublicTransport {
  teksi: number;
  bas: number;
  keretaApi: number;
  feri: number;
  lainLain: number;
}

export interface MealAllowance {
  sarapan: { bil: number; hari: number; kadar: number };
  makanTengahHari: { bil: number; hari: number; kadar: number };
  makanMalam: { bil: number; hari: number; kadar: number };
  harian: { bil: number; hari: number; kadar: number };
}

export interface HotelLodging {
  jenis: 'Hotel' | 'Lojing';
  bilangan: number;
  kadar: number;
  tarikh: string;
  alamat: string;
}

export interface MiscExpenses {
  telefon: number;
  pos: number;
  dobi: number;
  airportTax: number;
  lebihanBagasi: number;
  parking: number;
  tol: number;
}

export interface ClaimState {
  info: OfficerInfo;
  logs: JourneyLog[];
  transport: PublicTransport;
  meals: MealAllowance;
  lodgings: HotelLodging[];
  misc: MiscExpenses;
  advance: number;
}

export const KADAR_KERETA = {
  pertama: 0.85, // sen/km for first 500
  seterusnya: 0.75 // sen/km for 501 onwards
};

export const KADAR_MOTOSIKAL = {
  pertama: 0.55,
  seterusnya: 0.45
};

export const KADAR_MAKAN = {
  SARAPAN: 11.50,
  MAKAN_TENGAH_HARI: 15.50,
  MAKAN_MALAM: 18.00,
  HARIAN: 22.50
};

import React, { useState, useMemo } from 'react';
import { ClaimState, JourneyLog, HotelLodging } from './types';
import { KADAR_KERETA, KADAR_MOTOSIKAL, KADAR_MAKAN } from './constants';
import Step1OfficerInfo from './components/Step1OfficerInfo';
import Step2JourneyLog from './components/Step2JourneyLog';
import Step3PartA from './components/Step3PartA';
import Step4PartB from './components/Step4PartB';
import Step5Summary from './components/Step5Summary';

const initialClaim: ClaimState = {
  info: {
    nama: '', ic: '', jawatan: '', gred: '', akaunBank: '', namaBank: '', telefon: '',
    gaji: 0, elaun: 0, kenderaanJenis: 'Kereta', kenderaanModel: '', noPendaftaran: '',
    alamatPejabat: '', alamatRumah: ''
  },
  logs: [],
  transport: { teksi: 0, bas: 0, keretaApi: 0, feri: 0, lainLain: 0 },
  meals: {
    sarapan: { bil: 0, hari: 0, kadar: KADAR_MAKAN.SARAPAN },
    makanTengahHari: { bil: 0, hari: 0, kadar: KADAR_MAKAN.MAKAN_TENGAH_HARI },
    makanMalam: { bil: 0, hari: 0, kadar: KADAR_MAKAN.MAKAN_MALAM },
    harian: { bil: 0, hari: 0, kadar: KADAR_MAKAN.HARIAN },
  },
  lodgings: [],
  misc: { telefon: 0, pos: 0, dobi: 0, airportTax: 0, lebihanBagasi: 0, parking: 0, tol: 0 },
  advance: 0
};

const STEPS = [
  'Maklumat Pegawai',
  'Kenyataan Tuntutan',
  'Bahagian A (Kenderaan/Makan)',
  'Bahagian B (Hotel/Lojing)',
  'Rumusan & Pengakuan'
];

export default function App() {
  const [currentStep, setCurrentStep] = useState(0);
  const [formData, setFormData] = useState<ClaimState>(initialClaim);

  const updateInfo = (info: Partial<ClaimState['info']>) => {
    setFormData(prev => ({ ...prev, info: { ...prev.info, ...info } }));
  };

  const updateLogs = (logs: JourneyLog[]) => {
    setFormData(prev => ({ ...prev, logs }));
  };

  const updateTransport = (transport: Partial<ClaimState['transport']>) => {
    setFormData(prev => ({ ...prev, transport: { ...prev.transport, ...transport } }));
  };

  const updateMeals = (meals: Partial<ClaimState['meals']>) => {
    setFormData(prev => ({ ...prev, meals: { ...prev.meals, ...meals } }));
  };

  const updateLodgings = (lodgings: HotelLodging[]) => {
    setFormData(prev => ({ ...prev, lodgings }));
  };

  const updateMisc = (misc: Partial<ClaimState['misc']>) => {
    setFormData(prev => ({ ...prev, misc: { ...prev.misc, ...misc } }));
  };

  const updateAdvance = (val: number) => {
    setFormData(prev => ({ ...prev, advance: val }));
  };

  const nextStep = () => setCurrentStep(prev => Math.min(prev + 1, STEPS.length - 1));
  const prevStep = () => setCurrentStep(prev => Math.max(prev - 1, 0));

  return (
    <div className="min-h-screen pb-20">
      {/* Header */}
      <header className="bg-blue-900 text-white p-6 shadow-lg mb-8">
        <div className="max-w-5xl mx-auto flex flex-col md:flex-row justify-between items-center">
          <div>
            <h1 className="text-2xl font-bold tracking-tight">e-Tuntutan Perjalanan WP1.4</h1>
            <p className="text-blue-200 text-sm">Lampiran C - Borang Tuntutan Elaun Perjalanan Dalam Negeri</p>
          </div>
          <div className="text-right mt-4 md:mt-0">
            <span className="bg-blue-700 px-3 py-1 rounded-full text-xs font-mono">WP1.4 PEKELILING PERBENDAHARAAN</span>
          </div>
        </div>
      </header>

      <main className="max-w-5xl mx-auto px-4">
        {/* Steper */}
        <div className="flex flex-wrap gap-4 mb-8 justify-center overflow-x-auto py-2">
          {STEPS.map((step, idx) => (
            <div key={idx} className="flex items-center">
              <div className={`flex items-center justify-center w-8 h-8 rounded-full text-xs font-bold ${
                currentStep === idx ? 'bg-blue-600 text-white shadow-lg ring-4 ring-blue-100' : 
                currentStep > idx ? 'bg-green-500 text-white' : 'bg-gray-200 text-gray-500'
              }`}>
                {idx + 1}
              </div>
              <span className={`ml-2 text-xs hidden md:block font-medium ${currentStep === idx ? 'text-blue-700' : 'text-gray-400'}`}>
                {step}
              </span>
              {idx < STEPS.length - 1 && <div className="ml-4 h-[2px] w-4 bg-gray-200 hidden md:block" />}
            </div>
          ))}
        </div>

        {/* Form Content */}
        <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6 mb-24 transition-all duration-300">
          {currentStep === 0 && <Step1OfficerInfo info={formData.info} onChange={updateInfo} />}
          {currentStep === 1 && <Step2JourneyLog logs={formData.logs} onChange={updateLogs} />}
          {currentStep === 2 && (
            <Step3PartA 
              logs={formData.logs} 
              vehicleType={formData.info.kenderaanJenis}
              transport={formData.transport}
              meals={formData.meals}
              onTransportChange={updateTransport}
              onMealsChange={updateMeals}
            />
          )}
          {currentStep === 3 && <Step4PartB lodgings={formData.lodgings} onChange={updateLodgings} />}
          {currentStep === 4 && (
            <Step5Summary 
              data={formData} 
              onMiscChange={updateMisc} 
              onAdvanceChange={updateAdvance}
            />
          )}
        </div>
      </main>

      {/* Persistent Navigation Footer */}
      <footer className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 p-4 shadow-[0_-4px_10px_rgba(0,0,0,0.05)] z-50">
        <div className="max-w-5xl mx-auto flex justify-between items-center">
          <button 
            onClick={prevStep}
            disabled={currentStep === 0}
            className={`px-6 py-2 rounded-lg font-semibold transition-colors ${
              currentStep === 0 ? 'bg-gray-100 text-gray-400 cursor-not-allowed' : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
            }`}
          >
            Kembali
          </button>

          <div className="hidden md:flex flex-col items-center">
             <div className="text-[10px] text-gray-400 uppercase tracking-widest mb-1 font-bold">Progress</div>
             <div className="w-48 h-1 bg-gray-100 rounded-full overflow-hidden">
                <div 
                  className="h-full bg-blue-600 transition-all duration-500" 
                  style={{ width: `${((currentStep + 1) / STEPS.length) * 100}%` }}
                />
             </div>
          </div>

          <button 
            onClick={nextStep}
            disabled={currentStep === STEPS.length - 1}
            className={`px-8 py-2 rounded-lg font-semibold transition-all ${
              currentStep === STEPS.length - 1 ? 'bg-green-100 text-green-700 cursor-default' : 'bg-blue-600 text-white hover:bg-blue-700 shadow-md'
            }`}
          >
            {currentStep === STEPS.length - 1 ? 'Selesai' : 'Seterusnya'}
          </button>
        </div>
      </footer>
    </div>
  );
}

import React from 'react';
import { JourneyLog } from '../types';

interface Props {
  logs: JourneyLog[];
  onChange: (logs: JourneyLog[]) => void;
}

const Step2JourneyLog: React.FC<Props> = ({ logs, onChange }) => {
  const addRow = () => {
    const newLog: JourneyLog = {
      id: Math.random().toString(36).substr(2, 9),
      tarikh: '',
      waktuBertolak: '',
      waktuSampai: '',
      butiran: '',
      jarak: 0
    };
    onChange([...logs, newLog]);
  };

  const updateRow = (id: string, field: keyof JourneyLog, value: any) => {
    onChange(logs.map(log => log.id === id ? { ...log, [field]: value } : log));
  };

  const removeRow = (id: string) => {
    onChange(logs.filter(log => log.id !== id));
  };

  return (
    <div className="animate-fadeIn">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-xl font-bold text-gray-800">Log Perjalanan & Butiran Tuntutan</h2>
        <button 
          onClick={addRow}
          className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2"
        >
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4" /></svg>
          Tambah Baris
        </button>
      </div>

      <div className="overflow-x-auto border rounded-xl">
        <table className="min-w-full divide-y divide-gray-200">
          <thead className="bg-gray-50">
            <tr>
              <th className="px-4 py-3 text-left text-[10px] font-bold text-gray-500 uppercase">Tarikh</th>
              <th className="px-4 py-3 text-left text-[10px] font-bold text-gray-500 uppercase">Bertolak</th>
              <th className="px-4 py-3 text-left text-[10px] font-bold text-gray-500 uppercase">Sampai</th>
              <th className="px-4 py-3 text-left text-[10px] font-bold text-gray-500 uppercase">Butiran (Tujuan/Destinasi)</th>
              <th className="px-4 py-3 text-left text-[10px] font-bold text-gray-500 uppercase">Jarak (KM)</th>
              <th className="px-4 py-3 text-center text-[10px] font-bold text-gray-500 uppercase">Aksi</th>
            </tr>
          </thead>
          <tbody className="bg-white divide-y divide-gray-200">
            {logs.length === 0 ? (
              <tr>
                <td colSpan={6} className="px-4 py-10 text-center text-gray-400 italic">
                  Tiada log perjalanan. Klik "Tambah Baris" untuk mula.
                </td>
              </tr>
            ) : logs.map((log) => (
              <tr key={log.id} className="hover:bg-gray-50 transition-colors">
                <td className="px-2 py-2">
                  <input 
                    type="date" value={log.tarikh} 
                    onChange={(e) => updateRow(log.id, 'tarikh', e.target.value)}
                    className="w-full border-none focus:ring-0 text-sm p-1 bg-transparent"
                  />
                </td>
                <td className="px-2 py-2">
                  <input 
                    type="time" value={log.waktuBertolak} 
                    onChange={(e) => updateRow(log.id, 'waktuBertolak', e.target.value)}
                    className="w-full border-none focus:ring-0 text-sm p-1 bg-transparent"
                  />
                </td>
                <td className="px-2 py-2">
                  <input 
                    type="time" value={log.waktuSampai} 
                    onChange={(e) => updateRow(log.id, 'waktuSampai', e.target.value)}
                    className="w-full border-none focus:ring-0 text-sm p-1 bg-transparent"
                  />
                </td>
                <td className="px-2 py-2">
                  <input 
                    type="text" value={log.butiran} 
                    onChange={(e) => updateRow(log.id, 'butiran', e.target.value)}
                    className="w-full border-none focus:ring-0 text-sm p-1 bg-transparent"
                    placeholder="Contoh: Dari Pejabat ke Putrajaya"
                  />
                </td>
                <td className="px-2 py-2 w-24">
                  <input 
                    type="number" value={log.jarak} 
                    onChange={(e) => updateRow(log.id, 'jarak', parseFloat(e.target.value) || 0)}
                    className="w-full border-none focus:ring-0 text-sm p-1 bg-transparent text-right"
                  />
                </td>
                <td className="px-2 py-2 text-center">
                  <button 
                    onClick={() => removeRow(log.id)}
                    className="text-red-400 hover:text-red-600 p-1"
                  >
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
          <tfoot className="bg-blue-50">
            <tr>
              <td colSpan={4} className="px-4 py-3 text-sm font-bold text-blue-900 text-right uppercase">Jumlah Jarak</td>
              <td className="px-2 py-3 text-sm font-bold text-blue-900 text-right">
                {logs.reduce((sum, l) => sum + l.jarak, 0).toFixed(2)} KM
              </td>
              <td></td>
            </tr>
          </tfoot>
        </table>
      </div>
    </div>
  );
};

export default Step2JourneyLog;

import React, { useMemo } from 'react';
import { JourneyLog, PublicTransport, MealAllowance, ClaimState } from '../types';
import { KADAR_KERETA, KADAR_MOTOSIKAL } from '../constants';

interface Props {
  logs: JourneyLog[];
  vehicleType: 'Kereta' | 'Motosikal';
  transport: PublicTransport;
  meals: MealAllowance;
  onTransportChange: (val: Partial<PublicTransport>) => void;
  onMealsChange: (val: Partial<MealAllowance>) => void;
}

const Step3PartA: React.FC<Props> = ({ logs, vehicleType, transport, meals, onTransportChange, onMealsChange }) => {
  const totalKm = logs.reduce((sum, l) => sum + l.jarak, 0);
  const kadar = vehicleType === 'Kereta' ? KADAR_KERETA : KADAR_MOTOSIKAL;

  const mileageCalc = useMemo(() => {
    let km1 = Math.min(totalKm, 500);
    let km2 = Math.max(0, totalKm - 500);
    let amt1 = km1 * kadar.pertama;
    let amt2 = km2 * kadar.seterusnya;
    return { km1, km2, amt1, amt2, total: amt1 + amt2 };
  }, [totalKm, kadar]);

  const handleTransport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    onTransportChange({ [name]: parseFloat(value) || 0 });
  };

  const handleMeal = (part: keyof MealAllowance, field: 'bil' | 'hari', value: string) => {
    onMealsChange({ 
      [part]: { ...meals[part], [field]: parseInt(value) || 0 }
    });
  };

  const transportTotal = transport.teksi + transport.bas + transport.keretaApi + transport.feri + transport.lainLain;

  const mealTotal = 
    (meals.sarapan.bil * meals.sarapan.hari * meals.sarapan.kadar) +
    (meals.makanTengahHari.bil * meals.makanTengahHari.hari * meals.makanTengahHari.kadar) +
    (meals.makanMalam.bil * meals.makanMalam.hari * meals.makanMalam.kadar) +
    (meals.harian.bil * meals.harian.hari * meals.harian.kadar);

  return (
    <div className="space-y-10 animate-fadeIn">
      {/* Mileage */}
      <section>
        <h2 className="text-xl font-bold text-gray-800 border-b pb-2 mb-6 uppercase tracking-wide">Bahagian A: Elaun Perjalanan Kenderaan</h2>
        <div className="bg-blue-50 p-4 rounded-xl border border-blue-100 flex items-center justify-between mb-6">
          <span className="text-sm font-medium text-blue-800">Jenis Kenderaan terpilih:</span>
          <span className="bg-blue-600 text-white px-3 py-1 rounded-full text-xs font-bold">{vehicleType}</span>
        </div>
        <div className="overflow-hidden border rounded-xl">
          <table className="min-w-full divide-y divide-gray-200">
            <thead className="bg-gray-50">
              <tr>
                <th className="px-4 py-3 text-left text-xs font-bold text-gray-500 uppercase">Kiraan Kilometer</th>
                <th className="px-4 py-3 text-center text-xs font-bold text-gray-500 uppercase">Jarak (KM)</th>
                <th className="px-4 py-3 text-center text-xs font-bold text-gray-500 uppercase">Kadar Sekilometer</th>
                <th className="px-4 py-3 text-right text-xs font-bold text-gray-500 uppercase">Jumlah (RM)</th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
              <tr>
                <td className="px-4 py-3 text-sm">500 km pertama</td>
                <td className="px-4 py-3 text-center text-sm font-medium">{mileageCalc.km1}</td>
                <td className="px-4 py-3 text-center text-sm">RM {kadar.pertama.toFixed(2)}</td>
                <td className="px-4 py-3 text-right text-sm font-bold">RM {mileageCalc.amt1.toFixed(2)}</td>
              </tr>
              <tr>
                <td className="px-4 py-3 text-sm">501 km dan seterusnya</td>
                <td className="px-4 py-3 text-center text-sm font-medium">{mileageCalc.km2}</td>
                <td className="px-4 py-3 text-center text-sm">RM {kadar.seterusnya.toFixed(2)}</td>
                <td className="px-4 py-3 text-right text-sm font-bold">RM {mileageCalc.amt2.toFixed(2)}</td>
              </tr>
              <tr className="bg-blue-50">
                <td colSpan={3} className="px-4 py-3 text-sm font-bold text-blue-900 text-right uppercase">Jumlah Mileage</td>
                <td className="px-4 py-3 text-right text-sm font-bold text-blue-900">RM {mileageCalc.total.toFixed(2)}</td>
              </tr>
            </tbody>
          </table>
        </div>
      </section>

      {/* Public Transport */}
      <section>
        <h2 className="text-xl font-bold text-gray-800 border-b pb-2 mb-6 uppercase tracking-wide">Tuntutan Tambang Pengangkutan Awam</h2>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {Object.keys(transport).map((key) => (
            <div key={key} className="space-y-1">
              <label className="text-xs font-bold text-gray-500 uppercase">{key.replace(/([A-Z])/g, ' $1')}</label>
              <div className="relative">
                <span className="absolute left-3 top-2.5 text-gray-400 text-sm">RM</span>
                <input 
                  type="number" name={key} value={(transport as any)[key]} onChange={handleTransport}
                  className="w-full border rounded-lg p-2 pl-10 focus:ring-2 focus:ring-blue-500 outline-none text-right"
                />
              </div>
            </div>
          ))}
          <div className="md:col-span-2 lg:col-span-3 flex justify-end">
            <div className="bg-gray-100 px-6 py-2 rounded-lg border border-gray-200">
                <span className="text-sm font-bold text-gray-600 mr-4 uppercase">Jumlah Tambang</span>
                <span className="text-lg font-black text-gray-900">RM {transportTotal.toFixed(2)}</span>
            </div>
          </div>
        </div>
      </section>

      {/* Meals */}
      <section>
        <h2 className="text-xl font-bold text-gray-800 border-b pb-2 mb-6 uppercase tracking-wide">Tuntutan Elaun Makan / Harian</h2>
        <div className="overflow-x-auto border rounded-xl">
           <table className="min-w-full divide-y divide-gray-200">
             <thead className="bg-gray-50">
               <tr>
                 <th className="px-4 py-3 text-left text-xs font-bold text-gray-500 uppercase">Jenis Makan</th>
                 <th className="px-4 py-3 text-center text-xs font-bold text-gray-500 uppercase">Bil. Dituntut</th>
                 <th className="px-4 py-3 text-center text-xs font-bold text-gray-500 uppercase">Bil. Hari</th>
                 <th className="px-4 py-3 text-center text-xs font-bold text-gray-500 uppercase">Kadar (RM)</th>
                 <th className="px-4 py-3 text-right text-xs font-bold text-gray-500 uppercase">Jumlah (RM)</th>
               </tr>
             </thead>
             <tbody className="bg-white divide-y divide-gray-200">
               {(['sarapan', 'makanTengahHari', 'makanMalam', 'harian'] as const).map(m => (
                 <tr key={m}>
                   <td className="px-4 py-3 text-sm capitalize">{m.replace(/([A-Z])/g, ' $1')}</td>
                   <td className="px-4 py-2 text-center">
                     <input 
                        type="number" value={meals[m].bil} onChange={(e) => handleMeal(m, 'bil', e.target.value)}
                        className="w-16 border rounded p-1 text-center"
                     />
                   </td>
                   <td className="px-4 py-2 text-center">
                     <input 
                        type="number" value={meals[m].hari} onChange={(e) => handleMeal(m, 'hari', e.target.value)}
                        className="w-16 border rounded p-1 text-center"
                     />
                   </td>
                   <td className="px-4 py-3 text-center text-sm">RM {meals[m].kadar.toFixed(2)}</td>
                   <td className="px-4 py-3 text-right text-sm font-bold">
                      RM {(meals[m].bil * meals[m].hari * meals[m].kadar).toFixed(2)}
                   </td>
                 </tr>
               ))}
               <tr className="bg-green-50">
                 <td colSpan={4} className="px-4 py-3 text-sm font-bold text-green-900 text-right uppercase">Jumlah Elaun Makan/Harian</td>
                 <td className="px-4 py-3 text-right text-sm font-black text-green-900">RM {mealTotal.toFixed(2)}</td>
               </tr>
             </tbody>
           </table>
        </div>
      </section>
    </div>
  );
};

export default Step3PartA;

import React from 'react';
import { HotelLodging } from '../types';

interface Props {
  lodgings: HotelLodging[];
  onChange: (lodgings: HotelLodging[]) => void;
}

const Step4PartB: React.FC<Props> = ({ lodgings, onChange }) => {
  const addRow = () => {
    const newLodging: HotelLodging = {
      jenis: 'Hotel',
      bilangan: 0,
      kadar: 0,
      tarikh: '',
      alamat: ''
    };
    onChange([...lodgings, newLodging]);
  };

  const updateRow = (idx: number, field: keyof HotelLodging, value: any) => {
    const newRows = [...lodgings];
    newRows[idx] = { ...newRows[idx], [field]: value };
    onChange(newRows);
  };

  const removeRow = (idx: number) => {
    onChange(lodgings.filter((_, i) => i !== idx));
  };

  const total = lodgings.reduce((sum, l) => sum + (l.bilangan * l.kadar), 0);

  return (
    <div className="animate-fadeIn">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-xl font-bold text-gray-800 uppercase tracking-wide">Bahagian B: Tuntutan Bayaran Sewa Hotel (BSH) / Lojing</h2>
        <button 
          onClick={addRow}
          className="bg-green-600 hover:bg-green-700 text-white px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2"
        >
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4" /></svg>
          Tambah Tuntutan
        </button>
      </div>

      <div className="space-y-6">
        {lodgings.length === 0 ? (
           <div className="p-12 text-center border-2 border-dashed border-gray-200 rounded-2xl text-gray-400 italic">
              Tiada tuntutan hotel atau lojing ditambah.
           </div>
        ) : lodgings.map((l, idx) => (
          <div key={idx} className="bg-gray-50 border rounded-xl p-6 relative group hover:border-blue-300 transition-all shadow-sm hover:shadow-md">
            <button 
              onClick={() => removeRow(idx)}
              className="absolute top-4 right-4 text-gray-400 hover:text-red-500"
            >
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
            </button>
            <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
               <div className="space-y-1">
                 <label className="text-xs font-bold text-gray-500 uppercase">Jenis</label>
                 <select 
                   value={l.jenis} onChange={(e) => updateRow(idx, 'jenis', e.target.value)}
                   className="w-full border rounded-lg p-2 focus:ring-2 focus:ring-blue-500 outline-none"
                 >
                   <option value="Hotel">Hotel (BSH)</option>
                   <option value="Lojing">Lojing</option>
                 </select>
               </div>
               <div className="space-y-1">
                 <label className="text-xs font-bold text-gray-500 uppercase">Bil. Malam / Hari</label>
                 <input 
                   type="number" value={l.bilangan} onChange={(e) => updateRow(idx, 'bilangan', parseInt(e.target.value) || 0)}
                   className="w-full border rounded-lg p-2 focus:ring-2 focus:ring-blue-500 outline-none"
                 />
               </div>
               <div className="space-y-1">
                 <label className="text-xs font-bold text-gray-500 uppercase">Kadar (RM)</label>
                 <input 
                   type="number" value={l.kadar} onChange={(e) => updateRow(idx, 'kadar', parseFloat(e.target.value) || 0)}
                   className="w-full border rounded-lg p-2 focus:ring-2 focus:ring-blue-500 outline-none"
                 />
               </div>
               <div className="space-y-1">
                 <label className="text-xs font-bold text-gray-500 uppercase">Tarikh</label>
                 <input 
                   type="date" value={l.tarikh} onChange={(e) => updateRow(idx, 'tarikh', e.target.value)}
                   className="w-full border rounded-lg p-2 focus:ring-2 focus:ring-blue-500 outline-none"
                 />
               </div>
               <div className="md:col-span-4 space-y-1">
                 <label className="text-xs font-bold text-gray-500 uppercase">Alamat Hotel / Lojing</label>
                 <textarea 
                   value={l.alamat} onChange={(e) => updateRow(idx, 'alamat', e.target.value)}
                   className="w-full border rounded-lg p-2 focus:ring-2 focus:ring-blue-500 outline-none h-16"
                   placeholder="Masukkan nama hotel dan alamat penuh..."
                 />
               </div>
               <div className="md:col-span-4 flex justify-end items-center bg-white px-4 py-2 rounded-lg border">
                  <span className="text-xs font-bold text-gray-400 uppercase mr-4">Subjumlah</span>
                  <span className="text-lg font-bold text-gray-900">RM {(l.bilangan * l.kadar).toFixed(2)}</span>
               </div>
            </div>
          </div>
        ))}
      </div>

      <div className="mt-8 flex justify-end">
        <div className="bg-blue-900 text-white px-8 py-4 rounded-xl shadow-lg border-2 border-blue-800">
           <div className="text-[10px] uppercase font-bold text-blue-300 mb-1 tracking-widest">Jumlah Keseluruhan Bahagian B</div>
           <div className="text-3xl font-black">RM {total.toFixed(2)}</div>
        </div>
      </div>
    </div>
  );
};

