                <span className={`text-4xl font-black ${nettTotal >= 0 ? 'text-green-400' : 'text-red-400'}`}>
                  RM {Math.abs(nettTotal).toFixed(2)}
                  <span className="text-xs ml-2 font-normal">{nettTotal >= 0 ? '(TUNTUT)' : '(BALIK)'}</span>
