import { ClaimState } from './types';

const STORAGE_KEY = 'etuntutan_drafts';

export interface DraftEntry {
  id: string;
  name: string;
  lastUpdated: string;
  data: ClaimState;
}

export const persistence = {
  // Simpan draf ke LocalStorage
  saveDraft: (id: string, name: string, data: ClaimState) => {
    const existing = persistence.getAllDrafts();
    const newDraft: DraftEntry = {
      id,
      name,
      lastUpdated: new Date().toISOString(),
      data
    };

    const updated = { ...existing, [id]: newDraft };
    localStorage.setItem(STORAGE_KEY, JSON.stringify(updated));
  },

  // Ambil semua draf
  getAllDrafts: (): Record<string, DraftEntry> => {
    const data = localStorage.getItem(STORAGE_KEY);
    return data ? JSON.parse(data) : {};
  },

  // Ambil draf spesifik
  getDraft: (id: string): DraftEntry | null => {
    const drafts = persistence.getAllDrafts();
    return drafts[id] || null;
  },

  // Padam draf
  deleteDraft: (id: string) => {
    const drafts = persistence.getAllDrafts();
    delete drafts[id];
    localStorage.setItem(STORAGE_KEY, JSON.stringify(drafts));
  },

  // Eksport fail JSON
  exportData: (data: ClaimState) => {
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `tuntutan_${new Date().getTime()}.json`;
    a.click();
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { ClaimState, JourneyGroup, HotelLodging } from './types';
import { KADAR_KERETA, KADAR_MOTOSIKAL, KADAR_MAKAN } from './constants';
import { persistence, DraftEntry } from './persistence';
import Step1OfficerInfo from './Step1OfficerInfo';
import Step2JourneyLog from './Step2JourneyLog';
import Step3PartA from './Step3PartA';
import Step4PartB from './Step4PartB';
import Step5Summary from './Step5Summary';

const initialClaim: ClaimState = {
  info: {
    nama: '', ic: '', jawatan: '', gred: '', akaunBank: '', namaBank: '', telefon: '',
    gaji: 0, elaun: 0, kenderaanJenis: 'Kereta', kenderaanModel: '', noPendaftaran: '',
    alamatPejabat: '', alamatRumah: ''
  },
  logs: [],
  transport: { teksi: 0, bas: 0, keretaApi: 0, feri: 0, lainLain: 0 },
  meals: {
    sarapan: { bil: 0, hari: 0, kadar: KADAR_MAKAN.SARAPAN },
    makanTengahHari: { bil: 0, hari: 0, kadar: KADAR_MAKAN.MAKAN_TENGAH_HARI },
    makanMalam: { bil: 0, hari: 0, kadar: KADAR_MAKAN.MAKAN_MALAM },
    harian: { bil: 0, hari: 0, kadar: KADAR_MAKAN.HARIAN },
  },
  lodgings: [],
  misc: { telefon: 0, pos: 0, dobi: 0, airportTax: 0, lebihanBagasi: 0, parking: 0, tol: 0 },
  advance: 0
};

const STEPS = [
  'Maklumat Pegawai',
  'Kenyataan Tuntutan',
  'Bahagian A (Kenderaan/Makan)',
  'Bahagian B (Hotel/Lojing)',
  'Rumusan & Pengakuan'
];

export default function App() {
  const [currentStep, setCurrentStep] = useState(0);
  const [formData, setFormData] = useState<ClaimState>(initialClaim);
  const [currentDraftId, setCurrentDraftId] = useState<string>(() => 'draft_' + Date.now());
  const [saveStatus, setSaveStatus] = useState<'saved' | 'saving' | 'idle'>('idle');
  const [isDraftMenuOpen, setIsDraftMenuOpen] = useState(false);
  const [allDrafts, setAllDrafts] = useState<Record<string, DraftEntry>>({});

  // Muat draf terakhir pada startup
  useEffect(() => {
    const drafts = persistence.getAllDrafts();
    setAllDrafts(drafts);
    const lastId = Object.keys(drafts).sort((a, b) => 
      new Date(drafts[b].lastUpdated).getTime() - new Date(drafts[a].lastUpdated).getTime()
    )[0];

    if (lastId) {
      setCurrentDraftId(lastId);
      setFormData(drafts[lastId].data);
    }
  }, []);

  // Auto-save apabila formData berubah
  useEffect(() => {
    if (formData.info.nama || formData.logs.length > 0) {
      setSaveStatus('saving');
      const timer = setTimeout(() => {
        const name = formData.info.nama || 'Tuntutan Tanpa Nama';
        persistence.saveDraft(currentDraftId, name, formData);
        setAllDrafts(persistence.getAllDrafts());
        setSaveStatus('saved');
      }, 1000);
      return () => clearTimeout(timer);
    }
  }, [formData, currentDraftId]);

  const updateInfo = (info: Partial<ClaimState['info']>) => {
    setFormData(prev => ({ ...prev, info: { ...prev.info, ...info } }));
  };

  const updateLogs = (logs: JourneyGroup[]) => {
    setFormData(prev => ({ ...prev, logs }));
  };

  const updateTransport = (transport: Partial<ClaimState['transport']>) => {
    setFormData(prev => ({ ...prev, transport: { ...prev.transport, ...transport } }));
  };

  const updateMeals = (meals: Partial<ClaimState['meals']>) => {
    setFormData(prev => ({ ...prev, meals: { ...prev.meals, ...meals } }));
  };

  const updateLodgings = (lodgings: HotelLodging[]) => {
    setFormData(prev => ({ ...prev, lodgings }));
  };

  const updateMisc = (misc: Partial<ClaimState['misc']>) => {
    setFormData(prev => ({ ...prev, misc: { ...prev.misc, ...misc } }));
  };

  const updateAdvance = (val: number) => {
    setFormData(prev => ({ ...prev, advance: val }));
  };

  const nextStep = () => setCurrentStep(prev => Math.min(prev + 1, STEPS.length - 1));
  const prevStep = () => setCurrentStep(prev => Math.max(prev - 1, 0));

  const createNewDraft = () => {
    const newId = 'draft_' + Date.now();
    setCurrentDraftId(newId);
    setFormData(initialClaim);
    setIsDraftMenuOpen(false);
  };

  const loadDraft = (id: string) => {
    const draft = allDrafts[id];
    if (draft) {
      setCurrentDraftId(id);
      setFormData(draft.data);
      setIsDraftMenuOpen(false);
      setCurrentStep(0);
    }
  };

  const deleteDraft = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (confirm('Padam draf ini?')) {
      persistence.deleteDraft(id);
      setAllDrafts(persistence.getAllDrafts());
      if (id === currentDraftId) createNewDraft();
    }
  };

  return (
    <div className="min-h-screen pb-24 bg-gray-50 flex flex-col">
      {/* Draft Sidebar Overlay */}
      {isDraftMenuOpen && (
        <div className="fixed inset-0 bg-black/50 z-[100] flex justify-end transition-all no-print">
          <div className="w-80 bg-white h-full shadow-2xl p-6 overflow-y-auto animate-slideLeft">
            <div className="flex justify-between items-center mb-8">
              <h3 className="font-black text-xl text-gray-800 uppercase italic">Senarai Draf</h3>
              <button onClick={() => setIsDraftMenuOpen(false)} className="p-2 hover:bg-gray-100 rounded-full">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
            </div>
            <button 
              onClick={createNewDraft}
              className="w-full bg-blue-600 text-white py-4 rounded-2xl font-bold mb-6 flex items-center justify-center gap-2 hover:bg-blue-700 transition-colors shadow-lg shadow-blue-100"
            >
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4" /></svg>
              Tuntutan Baru
            </button>
            <div className="space-y-3">
              {Object.values(allDrafts).sort((a,b) => new Date(b.lastUpdated).getTime() - new Date(a.lastUpdated).getTime()).map(draft => (
                <div 
                  key={draft.id} 
                  onClick={() => loadDraft(draft.id)}
                  className={`p-4 rounded-2xl border-2 transition-all cursor-pointer group relative ${
                    draft.id === currentDraftId ? 'border-blue-500 bg-blue-50' : 'border-gray-100 hover:border-gray-300 bg-white'
                  }`}
                >
                  <div className="font-bold text-sm truncate pr-6 uppercase tracking-tight">{draft.name}</div>
                  <div className="text-[10px] text-gray-400 mt-1 uppercase font-bold">
                    {new Date(draft.lastUpdated).toLocaleString('ms-MY', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' })}
                  </div>
                  <button 
                    onClick={(e) => deleteDraft(draft.id, e)}
                    className="absolute top-4 right-4 text-gray-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"
                  >
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                  </button>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      <header className="bg-blue-900 text-white p-6 shadow-lg no-print sticky top-0 z-[60]">
        <div className="max-w-5xl mx-auto flex flex-col md:flex-row justify-between items-center gap-4">
          <div className="flex items-center gap-4">
            <button 
              onClick={() => setIsDraftMenuOpen(true)}
              className="bg-blue-800 p-3 rounded-2xl hover:bg-blue-700 transition-colors border border-blue-700 shadow-inner"
            >
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6h16M4 12h16M4 18h16" /></svg>
            </button>
            <div>
              <h1 className="text-xl font-black tracking-tight uppercase leading-none italic">e-Tuntutan <span className="text-blue-400">WP1.4</span></h1>
              <div className="flex items-center gap-2 mt-1">
                <div className={`w-2 h-2 rounded-full ${saveStatus === 'saving' ? 'bg-orange-400 animate-pulse' : 'bg-green-400'}`}></div>
                <span className="text-[10px] text-blue-300 font-bold uppercase tracking-widest">
                  {saveStatus === 'saving' ? 'Menyimpan...' : 'Data Tersimpan'}
                </span>
              </div>
            </div>
          </div>
          <div className="flex items-center gap-3">
             <button 
               onClick={() => persistence.exportData(formData)}
               className="bg-blue-800/50 hover:bg-blue-800 px-4 py-2 rounded-xl text-xs font-bold border border-blue-700 transition-all flex items-center gap-2"
             >
               <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1M16 9l-4-4m0 0L8 9m4-4v12" /></svg>
               Back-up JSON
             </button>
          </div>
        </div>
      </header>

      <main className="max-w-5xl mx-auto px-4 mt-8 flex-grow w-full">
        <div className="flex flex-wrap gap-4 mb-10 justify-center overflow-x-auto py-4 no-print">
          {STEPS.map((step, idx) => (
            <div key={idx} className="flex items-center">
              <div className={`flex items-center justify-center w-10 h-10 rounded-2xl text-sm font-black transition-all ${
                currentStep === idx ? 'bg-blue-600 text-white shadow-xl shadow-blue-200 -translate-y-1' : 
                currentStep > idx ? 'bg-green-500 text-white' : 'bg-white text-gray-300 border-2 border-gray-100'
              }`}>
                {idx + 1}
              </div>
              <span className={`ml-3 text-[10px] hidden md:block font-black uppercase tracking-widest ${currentStep === idx ? 'text-blue-700' : 'text-gray-300'}`}>
                {step}
              </span>
              {idx < STEPS.length - 1 && <div className="ml-6 h-[2px] w-6 bg-gray-100 hidden md:block rounded-full" />}
            </div>
          ))}
        </div>

        <div className="bg-white rounded-[2.5rem] shadow-[0_20px_50px_rgba(0,0,0,0.03)] border border-gray-100 p-8 md:p-12 mb-24 transition-all duration-500">
          {currentStep === 0 && <Step1OfficerInfo info={formData.info} onChange={updateInfo} />}
          {currentStep === 1 && <Step2JourneyLog logs={formData.logs} onChange={updateLogs} />}
          {currentStep === 2 && (
            <Step3PartA 
              logs={formData.logs} 
              vehicleType={formData.info.kenderaanJenis}
              transport={formData.transport}
              meals={formData.meals}
              onTransportChange={updateTransport}
              onMealsChange={updateMeals}
            />
          )}
          {currentStep === 3 && <Step4PartB lodgings={formData.lodgings} onChange={updateLodgings} />}
          {currentStep === 4 && (
            <Step5Summary 
              data={formData} 
              onMiscChange={updateMisc} 
              onAdvanceChange={updateAdvance}
            />
          )}
        </div>
      </main>

      <footer className="fixed bottom-0 left-0 right-0 bg-white/80 backdrop-blur-md border-t border-gray-100 p-5 shadow-[0_-10px_30px_rgba(0,0,0,0.03)] z-50 no-print">
        <div className="max-w-5xl mx-auto flex justify-between items-center">
          <button 
            onClick={prevStep}
            disabled={currentStep === 0}
            className={`px-8 py-3 rounded-2xl font-black text-sm uppercase tracking-widest transition-all ${
              currentStep === 0 ? 'text-gray-200 cursor-not-allowed' : 'bg-gray-50 text-gray-500 hover:bg-gray-100 active:scale-95'
            }`}
          >
            Kembali
          </button>

          <div className="hidden md:flex flex-col items-center">
             <div className="text-[10px] text-gray-300 uppercase tracking-[0.2em] mb-3 font-black">Tahap Kemajuan</div>
             <div className="w-64 h-2 bg-gray-50 rounded-full overflow-hidden p-0.5">
                <div 
                  className="h-full bg-blue-600 transition-all duration-700 rounded-full shadow-[0_0_10px_rgba(37,99,235,0.5)]" 
                  style={{ width: `${((currentStep + 1) / STEPS.length) * 100}%` }}
                />
             </div>
          </div>

          <button 
            onClick={nextStep}
            disabled={currentStep === STEPS.length - 1}
            className={`px-10 py-3 rounded-2xl font-black text-sm uppercase tracking-widest transition-all ${
              currentStep === STEPS.length - 1 ? 'bg-green-100 text-green-700 cursor-default' : 'bg-blue-600 text-white hover:bg-blue-700 shadow-xl shadow-blue-200 active:scale-95'
            }`}
          >
            {currentStep === STEPS.length - 1 ? 'Lengkap' : 'Langkah Seterusnya'}
          </button>
        </div>
      </footer>
    </div>
  );
}

