import { ClaimState } from './types';
import { db, doc, setDoc, getDocs, collection, deleteDoc } from './firebase';

const STORAGE_KEY = 'etuntutan_drafts';

export interface DraftEntry {
  id: string;
  name: string;
  lastUpdated: string;
  data: ClaimState;
}

export const persistence = {
  // Simpan draf ke LocalStorage & Firebase
  saveDraft: async (id: string, name: string, data: ClaimState) => {
    const lastUpdated = new Date().toISOString();
    const newDraft: DraftEntry = { id, name, lastUpdated, data };

    // 1. Simpan secara Lokal (Sentiasa pantas)
    const existing = persistence.getAllDrafts();
    const updated = { ...existing, [id]: newDraft };
    localStorage.setItem(STORAGE_KEY, JSON.stringify(updated));

    // 2. Simpan ke Firebase (Cloud Sync)
    try {
      await setDoc(doc(db, "tuntutan_drafts", id), newDraft);
      return true;
    } catch (error) {
      console.error("Gagal sync ke Firebase:", error);
      return false;
    }
  },

  // Ambil semua draf (Gabungan Lokal + Cloud)
  fetchDraftsFromCloud: async (): Promise<Record<string, DraftEntry>> => {
    try {
      const querySnapshot = await getDocs(collection(db, "tuntutan_drafts"));
      const cloudDrafts: Record<string, DraftEntry> = {};
      querySnapshot.forEach((doc) => {
        cloudDrafts[doc.id] = doc.data() as DraftEntry;
      });

      // Update local storage dengan data dari cloud
      if (Object.keys(cloudDrafts).length > 0) {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(cloudDrafts));
      }
      return cloudDrafts;
    } catch (error) {
      console.error("Gagal ambil data dari Firebase:", error);
      return persistence.getAllDrafts();
    }
  },

  getAllDrafts: (): Record<string, DraftEntry> => {
    const data = localStorage.getItem(STORAGE_KEY);
    return data ? JSON.parse(data) : {};
  },

  deleteDraft: async (id: string) => {
    // Padam Lokal
    const drafts = persistence.getAllDrafts();
    delete drafts[id];
    localStorage.setItem(STORAGE_KEY, JSON.stringify(drafts));

    // Padam Cloud
    try {
      await deleteDoc(doc(db, "tuntutan_drafts", id));
    } catch (e) {
      console.error("Gagal padam draf di cloud", e);
    }
  },

  exportData: (data: ClaimState) => {
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `tuntutan_${new Date().getTime()}.json`;
    a.click();
  }
};

import React, { useState, useEffect } from 'react';
import { ClaimState, JourneyGroup, HotelLodging } from './types';
import { KADAR_MAKAN } from './constants';
import { persistence, DraftEntry } from './persistence';
import Step1OfficerInfo from './Step1OfficerInfo';
import Step2JourneyLog from './Step2JourneyLog';
import Step3PartA from './Step3PartA';
import Step4PartB from './Step4PartB';
import Step5Summary from './Step5Summary';

const initialClaim: ClaimState = {
  info: {
    nama: '', ic: '', jawatan: '', gred: '', akaunBank: '', namaBank: '', telefon: '',
    gaji: 0, elaun: 0, kenderaanJenis: 'Kereta', kenderaanModel: '', noPendaftaran: '',
    alamatPejabat: '', alamatRumah: ''
  },
  logs: [],
  transport: { teksi: 0, bas: 0, keretaApi: 0, feri: 0, lainLain: 0 },
  meals: {
    sarapan: { bil: 0, hari: 0, kadar: KADAR_MAKAN.SARAPAN },
    makanTengahHari: { bil: 0, hari: 0, kadar: KADAR_MAKAN.MAKAN_TENGAH_HARI },
    makanMalam: { bil: 0, hari: 0, kadar: KADAR_MAKAN.MAKAN_MALAM },
    harian: { bil: 0, hari: 0, kadar: KADAR_MAKAN.HARIAN },
  },
  lodgings: [],
  misc: { telefon: 0, pos: 0, dobi: 0, airportTax: 0, lebihanBagasi: 0, parking: 0, tol: 0 },
  advance: 0
};

const STEPS = [
  'Maklumat Pegawai',
  'Kenyataan Tuntutan',
  'Bahagian A',
  'Bahagian B',
  'Rumusan'
];

export default function App() {
  const [currentStep, setCurrentStep] = useState(0);
  const [formData, setFormData] = useState<ClaimState>(initialClaim);
  const [currentDraftId, setCurrentDraftId] = useState<string>(() => 'draft_' + Date.now());
  const [saveStatus, setSaveStatus] = useState<'saved' | 'saving' | 'error' | 'idle'>('idle');
  const [isDraftMenuOpen, setIsDraftMenuOpen] = useState(false);
  const [allDrafts, setAllDrafts] = useState<Record<string, DraftEntry>>({});

  // 1. Muat data dari Firebase/Lokal semasa startup
  useEffect(() => {
    const initData = async () => {
      setSaveStatus('saving');
      const cloudData = await persistence.fetchDraftsFromCloud();
      setAllDrafts(cloudData);

      const lastId = Object.keys(cloudData).sort((a, b) => 
        new Date(cloudData[b].lastUpdated).getTime() - new Date(cloudData[a].lastUpdated).getTime()
      )[0];

      if (lastId) {
        setCurrentDraftId(lastId);
        setFormData(cloudData[lastId].data);
      }
      setSaveStatus('saved');
    };
    initData();
  }, []);

  // 2. Auto-save Sync ke Firebase
  useEffect(() => {
    if (formData.info.nama || formData.logs.length > 0) {
      setSaveStatus('saving');
      const timer = setTimeout(async () => {
        const name = formData.info.nama || 'Tuntutan Tanpa Nama';
        const success = await persistence.saveDraft(currentDraftId, name, formData);
        setAllDrafts(persistence.getAllDrafts());
        setSaveStatus(success ? 'saved' : 'error');
      }, 2000); // 2 saat debouncing supaya tidak terlalu banyak request ke Firebase
      return () => clearTimeout(timer);
    }
  }, [formData, currentDraftId]);

  const updateInfo = (info: Partial<ClaimState['info']>) => setFormData(p => ({ ...p, info: { ...p.info, ...info } }));
  const updateLogs = (logs: JourneyGroup[]) => setFormData(p => ({ ...p, logs }));
  const updateTransport = (t: Partial<ClaimState['transport']>) => setFormData(p => ({ ...p, transport: { ...p.transport, ...t } }));
  const updateMeals = (m: Partial<ClaimState['meals']>) => setFormData(p => ({ ...p, meals: { ...p.meals, ...m } }));
  const updateLodgings = (l: HotelLodging[]) => setFormData(p => ({ ...p, lodgings: l }));
  const updateMisc = (m: Partial<ClaimState['misc']>) => setFormData(p => ({ ...p, misc: { ...p.misc, ...m } }));
  const updateAdvance = (v: number) => setFormData(p => ({ ...p, advance: v }));

  const nextStep = () => setCurrentStep(prev => Math.min(prev + 1, STEPS.length - 1));
  const prevStep = () => setCurrentStep(prev => Math.max(prev - 1, 0));

  const createNewDraft = () => {
    setCurrentDraftId('draft_' + Date.now());
    setFormData(initialClaim);
    setIsDraftMenuOpen(false);
  };

  const loadDraft = (id: string) => {
    const draft = allDrafts[id];
    if (draft) {
      setCurrentDraftId(id);
      setFormData(draft.data);
      setIsDraftMenuOpen(false);
      setCurrentStep(0);
    }
  };

  return (
    <div className="min-h-screen pb-24 bg-gray-50 flex flex-col">
      {/* Draft Sidebar */}
      {isDraftMenuOpen && (
        <div className="fixed inset-0 bg-black/60 z-[100] flex justify-end no-print backdrop-blur-sm transition-all">
          <div className="w-80 bg-white h-full shadow-2xl p-6 overflow-y-auto animate-slideLeft border-l border-gray-100">
            <div className="flex justify-between items-center mb-8">
              <h3 className="font-black text-xl text-gray-800 uppercase italic tracking-tighter">Draf di Firebase</h3>
              <button onClick={() => setIsDraftMenuOpen(false)} className="p-2 hover:bg-gray-100 rounded-full transition-colors">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
            </div>
            <button onClick={createNewDraft} className="w-full bg-blue-600 text-white py-4 rounded-2xl font-bold mb-6 hover:bg-blue-700 shadow-xl shadow-blue-100 transition-all active:scale-95 flex items-center justify-center gap-2">
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4" /></svg>
              Draf Baru
            </button>
            <div className="space-y-3">
              {Object.values(allDrafts).sort((a,b) => new Date(b.lastUpdated).getTime() - new Date(a.lastUpdated).getTime()).map(draft => (
                <div key={draft.id} onClick={() => loadDraft(draft.id)} className={`p-4 rounded-2xl border-2 transition-all cursor-pointer group ${draft.id === currentDraftId ? 'border-blue-500 bg-blue-50' : 'border-gray-50 bg-white hover:border-blue-200'}`}>
                  <div className="font-bold text-sm truncate uppercase">{draft.name}</div>
                  <div className="text-[10px] text-gray-400 mt-1 font-mono">{new Date(draft.lastUpdated).toLocaleString()}</div>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      <header className="bg-blue-900 text-white p-6 shadow-xl no-print sticky top-0 z-[60]">
        <div className="max-w-5xl mx-auto flex justify-between items-center">
          <div className="flex items-center gap-5">
            <button onClick={() => setIsDraftMenuOpen(true)} className="bg-blue-800 p-3 rounded-2xl hover:bg-blue-700 border border-blue-700 shadow-inner">
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6h16M4 12h16M4 18h16" /></svg>
            </button>
            <div>
              <h1 className="text-xl font-black italic uppercase tracking-tighter">e-Tuntutan <span className="text-blue-400">Firebase</span></h1>
              <div className="flex items-center gap-2 mt-1">
                <div className={`w-2 h-2 rounded-full ${saveStatus === 'saving' ? 'bg-orange-400 animate-pulse' : saveStatus === 'error' ? 'bg-red-500' : 'bg-green-400'}`}></div>
                <span className="text-[10px] text-blue-300 font-black uppercase tracking-widest flex items-center gap-1">
                  <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 15a4 4 0 004 4h9a5 5 0 10-.1-9.999 5.002 5.002 0 10-9.78 2.096A4.001 4.001 0 003 15z" /></svg>
                  {saveStatus === 'saving' ? 'Menyelaras ke Cloud...' : saveStatus === 'error' ? 'Gagal Sync' : 'Pangkalan Data Awan Aktif'}
                </span>
              </div>
            </div>
          </div>
        </div>
      </header>

      <main className="max-w-5xl mx-auto px-4 mt-8 flex-grow w-full">
        {/* Step Navigation Bar */}
        <div className="flex justify-center gap-3 mb-10 no-print overflow-x-auto py-2">
          {STEPS.map((step, idx) => (
            <div key={idx} className={`flex items-center gap-2 px-4 py-2 rounded-2xl transition-all ${currentStep === idx ? 'bg-blue-600 text-white shadow-lg' : 'bg-white text-gray-400 border border-gray-100'}`}>
              <span className="text-sm font-black">{idx + 1}</span>
              <span className="text-[10px] font-bold uppercase hidden md:inline">{step}</span>
            </div>
          ))}
        </div>

        <div className="bg-white rounded-[2.5rem] shadow-2xl shadow-gray-200 border border-gray-100 p-8 md:p-12 mb-24 min-h-[500px]">
          {currentStep === 0 && <Step1OfficerInfo info={formData.info} onChange={updateInfo} />}
          {currentStep === 1 && <Step2JourneyLog logs={formData.logs} onChange={updateLogs} />}
          {currentStep === 2 && <Step3PartA logs={formData.logs} vehicleType={formData.info.kenderaanJenis} transport={formData.transport} meals={formData.meals} onTransportChange={updateTransport} onMealsChange={updateMeals} />}
          {currentStep === 3 && <Step4PartB lodgings={formData.lodgings} onChange={updateLodgings} />}
          {currentStep === 4 && <Step5Summary data={formData} onMiscChange={updateMisc} onAdvanceChange={updateAdvance} />}
        </div>
      </main>

      <footer className="fixed bottom-0 left-0 right-0 bg-white/90 backdrop-blur-xl border-t border-gray-100 p-5 z-50 no-print">
        <div className="max-w-5xl mx-auto flex justify-between items-center">
          <button onClick={prevStep} disabled={currentStep === 0} className={`px-10 py-3 rounded-2xl font-black text-xs uppercase tracking-widest ${currentStep === 0 ? 'text-gray-200' : 'bg-gray-100 text-gray-500 hover:bg-gray-200'}`}>Kembali</button>
          <button onClick={nextStep} disabled={currentStep === STEPS.length - 1} className={`px-10 py-3 rounded-2xl font-black text-xs uppercase tracking-widest ${currentStep === STEPS.length - 1 ? 'bg-green-100 text-green-700' : 'bg-blue-600 text-white hover:bg-blue-700'}`}>
            {currentStep === STEPS.length - 1 ? 'Selesai' : 'Langkah Seterusnya'}
          </button>
        </div>
      </footer>
    </div>
  );
}

