            </button>
            <div className="space-y-3">
              {Object.values(allDrafts).sort((a,b) => new Date(b.lastUpdated).getTime() - new Date(a.lastUpdated).getTime()).map(draft => (
                <div key={draft.id} onClick={() => loadDraft(draft.id)} className={`p-4 rounded-2xl border-2 transition-all cursor-pointer group ${draft.id === currentDraftId ? 'border-blue-500 bg-blue-50' : 'border-gray-50 bg-white hover:border-blue-200'}`}>
                  <div className="font-bold text-sm truncate uppercase">{draft.name}</div>
                  <div className="text-[10px] text-gray-400 mt-1 font-mono">{new Date(draft.lastUpdated).toLocaleString()}</div>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      <header className="bg-blue-900 text-white p-6 shadow-xl no-print sticky top-0 z-[60]">
        <div className="max-w-5xl mx-auto flex justify-between items-center">
          <div className="flex items-center gap-5">
            <button onClick={() => setIsDraftMenuOpen(true)} className="bg-blue-800 p-3 rounded-2xl hover:bg-blue-700 border border-blue-700 shadow-inner transition-all">
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6h16M4 12h16M4 18h16" /></svg>
            </button>
            <div>
              <h1 className="text-xl font-black italic uppercase tracking-tighter">e-Tuntutan <span className="text-blue-400">{cloudActive ? 'Firebase' : 'Local'}</span></h1>
              <div className="flex items-center gap-2 mt-1">
                <div className={`w-2 h-2 rounded-full ${
                  !cloudActive ? 'bg-gray-400' :
                  saveStatus === 'saving' ? 'bg-orange-400 animate-pulse' : 
                  saveStatus === 'error' ? 'bg-red-500' : 'bg-green-400'
                }`}></div>
                <span className="text-[10px] text-blue-300 font-black uppercase tracking-widest flex items-center gap-1">
                  {!cloudActive ? 'Mod Simpanan Tempatan Sahaja' : 
                   saveStatus === 'saving' ? 'Menyelaras ke Cloud...' : 
                   saveStatus === 'error' ? 'Ralat Sambungan' : 'Pangkalan Data Cloud Aktif'}
                </span>
              </div>
            </div>
          </div>
          {!cloudActive && (
            <div className="hidden md:block bg-orange-500/20 text-orange-200 px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-tighter border border-orange-500/30">
              Konfigurasi Firebase Diperlukan
            </div>
          )}
        </div>
      </header>

      <main className="max-w-5xl mx-auto px-4 mt-8 flex-grow w-full">
        <div className="flex justify-center gap-3 mb-10 no-print overflow-x-auto py-2">
          {STEPS.map((step, idx) => (
            <div key={idx} className={`flex items-center gap-2 px-4 py-2 rounded-2xl transition-all ${currentStep === idx ? 'bg-blue-600 text-white shadow-lg' : 'bg-white text-gray-400 border border-gray-100'}`}>
              <span className="text-sm font-black">{idx + 1}</span>
              <span className="text-[10px] font-bold uppercase hidden md:inline">{step}</span>
            </div>
          ))}
        </div>

        <div className="bg-white rounded-[2.5rem] shadow-2xl shadow-gray-200 border border-gray-100 p-8 md:p-12 mb-24 min-h-[500px]">
          {currentStep === 0 && <Step1OfficerInfo info={formData.info} onChange={updateInfo} />}
          {currentStep === 1 && <Step2JourneyLog logs={formData.logs} onChange={updateLogs} />}
          {currentStep === 2 && <Step3PartA logs={formData.logs} vehicleType={formData.info.kenderaanJenis} transport={formData.transport} meals={formData.meals} onTransportChange={updateTransport} onMealsChange={updateMeals} />}
          {currentStep === 3 && <Step4PartB lodgings={formData.lodgings} onChange={updateLodgings} />}
          {currentStep === 4 && <Step5Summary data={formData} onMiscChange={updateMisc} onAdvanceChange={updateAdvance} />}
        </div>
      </main>

      <footer className="fixed bottom-0 left-0 right-0 bg-white/90 backdrop-blur-xl border-t border-gray-100 p-5 z-50 no-print">
        <div className="max-w-5xl mx-auto flex justify-between items-center">
          <button onClick={prevStep} disabled={currentStep === 0} className={`px-10 py-3 rounded-2xl font-black text-xs uppercase tracking-widest transition-all ${currentStep === 0 ? 'text-gray-200 cursor-not-allowed' : 'bg-gray-100 text-gray-500 hover:bg-gray-200 active:scale-95'}`}>Kembali</button>
          <button onClick={nextStep} disabled={currentStep === STEPS.length - 1} className={`px-10 py-3 rounded-2xl font-black text-xs uppercase tracking-widest transition-all ${currentStep === STEPS.length - 1 ? 'bg-green-100 text-green-700' : 'bg-blue-600 text-white hover:bg-blue-700 shadow-lg active:scale-95'}`}>
            {currentStep === STEPS.length - 1 ? 'Selesai' : 'Langkah Seterusnya'}
          </button>
        </div>
      </footer>
    </div>
  );
}

