          {currentStep === 1 && <Step2JourneyLog logs={formData.logs} onChange={(l) => setFormData(p => ({ ...p, logs: l }))} />}
          {currentStep === 2 && <Step3PartA logs={formData.logs} vehicleType={formData.info.kenderaanJenis} transport={formData.transport} meals={formData.meals} onTransportChange={(t) => setFormData(p => ({ ...p, transport: { ...p.transport, ...t } }))} onMealsChange={(m) => setFormData(p => ({ ...p, meals: { ...p.meals, ...m } }))} />}
          {currentStep === 3 && <Step4PartB lodgings={formData.lodgings} onChange={(l) => setFormData(p => ({ ...p, lodgings: l }))} />}
          {currentStep === 4 && <Step5Summary data={formData} onMiscChange={(m) => setFormData(p => ({ ...p, misc: { ...p.misc, ...m } }))} onAdvanceChange={(a) => setFormData(p => ({ ...p, advance: a }))} />}
        </div>
      </main>

      {/* Navigasi Bawah */}
      <footer className="fixed bottom-0 left-0 right-0 bg-white/90 backdrop-blur-xl border-t border-gray-100 p-5 z-50 no-print">
        <div className="max-w-5xl mx-auto flex justify-between items-center">
          <button 
            onClick={() => setCurrentStep(p => Math.max(0, p - 1))} 
            disabled={currentStep === 0}
            className={`px-10 py-3 rounded-2xl font-black text-xs uppercase tracking-widest transition-all ${currentStep === 0 ? 'text-gray-200 cursor-not-allowed' : 'bg-gray-100 text-gray-500 hover:bg-gray-200'}`}
          >
            Kembali
          </button>
          <button 
            onClick={() => setCurrentStep(p => Math.min(STEPS.length - 1, p + 1))} 
            disabled={currentStep === STEPS.length - 1}
            className={`px-10 py-3 rounded-2xl font-black text-xs uppercase tracking-widest transition-all ${currentStep === STEPS.length - 1 ? 'bg-green-100 text-green-700' : 'bg-blue-600 text-white hover:bg-blue-700 shadow-lg'}`}
          >
            Langkah Seterusnya
          </button>
        </div>
      </footer>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { ClaimState, JourneyGroup, HotelLodging } from './types';
import { KADAR_MAKAN } from './constants';
import { persistence, DraftEntry } from './persistence';
import { auth, onAuthStateChanged, signOut } from './firebase';
import Step1OfficerInfo from './Step1OfficerInfo';
import Step2JourneyLog from './Step2JourneyLog';
import Step3PartA from './Step3PartA';
import Step4PartB from './Step4PartB';
import Step5Summary from './Step5Summary';
import Auth from './Auth';

const initialClaim: ClaimState = {
  info: {
    nama: '', ic: '', jawatan: '', gred: '', akaunBank: '', namaBank: '', telefon: '',
    gaji: 0, elaun: 0, kenderaanJenis: 'Kereta', kenderaanModel: '', noPendaftaran: '',
    alamatPejabat: '', alamatRumah: ''
  },
  logs: [],
  transport: { teksi: 0, bas: 0, keretaApi: 0, feri: 0, lainLain: 0 },
  meals: {
    sarapan: { bil: 0, hari: 0, kadar: KADAR_MAKAN.SARAPAN },
    makanTengahHari: { bil: 0, hari: 0, kadar: KADAR_MAKAN.MAKAN_TENGAH_HARI },
    makanMalam: { bil: 0, hari: 0, kadar: KADAR_MAKAN.MAKAN_MALAM },
    harian: { bil: 0, hari: 0, kadar: KADAR_MAKAN.HARIAN },
  },
  lodgings: [],
  misc: { telefon: 0, pos: 0, dobi: 0, airportTax: 0, lebihanBagasi: 0, parking: 0, tol: 0 },
  advance: 0
};

const STEPS = [
  { label: 'Maklumat Pegawai', icon: 'M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z' },
  { label: 'Log Perjalanan', icon: 'M9 20l-5.447-2.724A1 1 0 013 16.382V5.618a1 1 0 011.447-.894L9 7m0 13l6-3m-6 3V7m6 10l4.553 2.276A1 1 0 0021 18.382V7.618a1 1 0 00-1.447-.894L15 9m0 8V9' },
  { label: 'Bahagian A', icon: 'M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z' },
  { label: 'Bahagian B', icon: 'M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4' },
  { label: 'Rumusan', icon: 'M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z' }
];

export default function App() {
  const [user, setUser] = useState<any>(null);
  const [authChecking, setAuthChecking] = useState(true);
  const [currentStep, setCurrentStep] = useState(0);
  const [formData, setFormData] = useState<ClaimState>(initialClaim);
  const [currentDraftId, setCurrentDraftId] = useState<string>(() => 'draft_' + Date.now());
  const [saveStatus, setSaveStatus] = useState<'saved' | 'saving' | 'error' | 'idle'>('idle');
  const [isDraftMenuOpen, setIsDraftMenuOpen] = useState(false);
  const [allDrafts, setAllDrafts] = useState<Record<string, DraftEntry>>({});

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
      setAuthChecking(false);
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    if (user) {
      const initData = async () => {
        setSaveStatus('saving');
        const data = await persistence.fetchDraftsForUser(user.uid);
        setAllDrafts(data);
        const lastId = Object.keys(data).sort((a, b) => new Date(data[b].lastUpdated).getTime() - new Date(data[a].lastUpdated).getTime())[0];
        if (lastId) {
          setCurrentDraftId(lastId);
          setFormData(data[lastId].data);
        }
        setSaveStatus('saved');
      };
      initData();
    }
  }, [user]);

  useEffect(() => {
    if (user && (formData.info.nama || formData.logs.length > 0)) {
      setSaveStatus('saving');
      const timer = setTimeout(async () => {
        const name = formData.info.nama || 'Tuntutan Tanpa Nama';
        const success = await persistence.saveDraft(currentDraftId, user.uid, name, formData);
        setAllDrafts(persistence.getAllDrafts());
        setSaveStatus(success ? 'saved' : 'error');
      }, 2000);
      return () => clearTimeout(timer);
    }
  }, [formData, currentDraftId, user]);

  const handleLogout = async () => {
    await signOut(auth);
    setFormData(initialClaim);
    setCurrentStep(0);
  };

  if (authChecking) return (
    <div className="min-h-screen flex items-center justify-center bg-slate-950">
      <div className="text-center">
        <div className="w-12 h-12 border-2 border-blue-500/20 border-t-blue-500 rounded-full animate-spin mx-auto mb-6"></div>
        <p className="text-slate-400 font-bold uppercase tracking-[0.2em] text-[10px]">Sistem Sedang Memuatkan</p>
      </div>
    </div>
  );

  if (!user) return <Auth onLoginSuccess={() => {}} />;

  return (
    <div className="min-h-screen pb-32 bg-slate-50/50 flex flex-col font-sans">
      {/* Side Navigation Overlay (Drafts) */}
      {isDraftMenuOpen && (
        <div className="fixed inset-0 bg-slate-900/40 z-[100] flex justify-end no-print backdrop-blur-md">
          <div className="w-96 bg-white h-full shadow-2xl p-8 overflow-y-auto animate-slideLeft border-l border-slate-100">
             <div className="flex justify-between items-center mb-10">
                <h3 className="font-black text-2xl text-slate-800 tracking-tighter">Arkib Tuntutan</h3>
                <button onClick={() => setIsDraftMenuOpen(false)} className="p-3 bg-slate-50 hover:bg-slate-100 rounded-2xl transition-all">
                  <svg className="w-5 h-5 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
             </div>
             <button onClick={() => { setCurrentDraftId('draft_'+Date.now()); setFormData(initialClaim); setIsDraftMenuOpen(false); }} className="w-full bg-blue-600 text-white py-5 rounded-[1.5rem] font-bold mb-8 hover:bg-blue-700 shadow-xl shadow-blue-200 transition-all flex items-center justify-center gap-3 active:scale-[0.98]">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4" /></svg>
                Mulakan Tuntutan Baru
             </button>
             <div className="space-y-4">
                {Object.values(allDrafts).sort((a,b) => new Date(b.lastUpdated).getTime() - new Date(a.lastUpdated).getTime()).map(draft => (
                  <div key={draft.id} onClick={() => { setCurrentDraftId(draft.id); setFormData(draft.data); setIsDraftMenuOpen(false); setCurrentStep(0); }} className={`p-5 rounded-3xl border-2 transition-all cursor-pointer group ${draft.id === currentDraftId ? 'border-blue-500 bg-blue-50/50' : 'border-slate-50 bg-white hover:border-slate-200'}`}>
                    <div className="font-black text-xs text-slate-800 uppercase tracking-wide truncate">{draft.name || 'Draf Tanpa Nama'}</div>
                    <div className="text-[9px] text-slate-400 mt-1.5 font-bold uppercase tracking-widest">{new Date(draft.lastUpdated).toLocaleDateString('ms-MY', { day:'2-digit', month:'short', year:'numeric', hour:'2-digit', minute:'2-digit' })}</div>
                  </div>
                ))}
             </div>
             <div className="mt-12 pt-10 border-t border-slate-100">
                <button onClick={handleLogout} className="w-full py-4 text-slate-400 hover:text-red-500 text-[10px] font-black uppercase tracking-widest transition-colors flex items-center justify-center gap-2">
                   Log Keluar dari Sistem
                </button>
             </div>
          </div>
        </div>
      )}

      {/* Modern Header */}
      <header className="bg-white/80 backdrop-blur-xl border-b border-slate-100 p-6 no-print sticky top-0 z-[60]">
        <div className="max-w-6xl mx-auto flex justify-between items-center">
          <div className="flex items-center gap-6">
            <button onClick={() => setIsDraftMenuOpen(true)} className="p-3.5 bg-slate-50 text-slate-500 rounded-2xl hover:bg-slate-100 transition-all active:scale-95 border border-slate-100">
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M4 6h16M4 12h16M4 18h7" /></svg>
            </button>
            <div>
              <h1 className="text-xl font-black text-slate-900 tracking-tighter uppercase leading-none">Tuntutan Perjalanan <span className="text-blue-600">Dalam Negeri</span></h1>
              <div className="flex items-center gap-2 mt-2">
                <span className={`w-1.5 h-1.5 rounded-full ${saveStatus === 'saving' ? 'bg-orange-500 animate-pulse' : 'bg-green-500'}`}></span>
                <span className="text-[9px] text-slate-400 font-bold uppercase tracking-widest">
                  {user.email} • {saveStatus === 'saving' ? 'Menyelaras Data...' : 'Sistem Aktif & Terselaras'}
                </span>
              </div>
            </div>
          </div>
          <div className="bg-slate-50 px-4 py-2 rounded-2xl border border-slate-100 hidden sm:block">
             <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-0.5">Versi Sistem</span>
             <span className="text-xs font-bold text-slate-600 uppercase">WP 1.4 Digital v2.5</span>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-6xl mx-auto px-4 mt-12 flex-grow w-full">
        {/* Step Indicator */}
        <div className="flex justify-between items-center mb-12 no-print gap-2 overflow-x-auto pb-4 px-2">
          {STEPS.map((step, idx) => (
            <div key={idx} className={`flex items-center gap-3 transition-all ${currentStep === idx ? 'opacity-100' : 'opacity-30'}`}>
              <div className={`w-10 h-10 rounded-2xl flex items-center justify-center transition-all ${currentStep === idx ? 'bg-blue-600 text-white shadow-lg shadow-blue-200' : 'bg-slate-200 text-slate-500'}`}>
                 <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d={step.icon} /></svg>
              </div>
              <div className="hidden lg:block text-left">
                 <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest block">Langkah {idx + 1}</span>
                 <span className="text-xs font-bold text-slate-800 uppercase">{step.label}</span>
              </div>
              {idx < STEPS.length - 1 && <div className="hidden lg:block w-8 h-[2px] bg-slate-200 mx-2"></div>}
            </div>
          ))}
        </div>

        {/* Content Area */}
        <div className="bg-white rounded-[3rem] shadow-2xl shadow-slate-200/50 border border-slate-100/50 overflow-hidden min-h-[600px] mb-20">
          <div className="p-8 md:p-16">
            {currentStep === 0 && <Step1OfficerInfo info={formData.info} onChange={(i) => setFormData(p => ({ ...p, info: { ...p.info, ...i } }))} />}
            {currentStep === 1 && <Step2JourneyLog logs={formData.logs} onChange={(l) => setFormData(p => ({ ...p, logs: l }))} />}
            {currentStep === 2 && <Step3PartA logs={formData.logs} vehicleType={formData.info.kenderaanJenis} transport={formData.transport} meals={formData.meals} onTransportChange={(t) => setFormData(p => ({ ...p, transport: { ...p.transport, ...t } }))} onMealsChange={(m) => setFormData(p => ({ ...p, meals: { ...p.meals, ...m } }))} />}
            {currentStep === 3 && <Step4PartB lodgings={formData.lodgings} onChange={(l) => setFormData(p => ({ ...p, lodgings: l }))} />}
            {currentStep === 4 && <Step5Summary data={formData} onMiscChange={(m) => setFormData(p => ({ ...p, misc: { ...p.misc, ...m } }))} onAdvanceChange={(a) => setFormData(p => ({ ...p, advance: a }))} />}
          </div>
        </div>
      </main>

      {/* Floating Action Bar */}
      <footer className="fixed bottom-8 left-0 right-0 flex justify-center z-50 no-print pointer-events-none px-6">
        <div className="bg-slate-900/90 backdrop-blur-2xl px-6 py-4 rounded-[2rem] shadow-2xl flex items-center gap-8 pointer-events-auto border border-slate-800">
           <button 
             onClick={() => { window.scrollTo(0,0); setCurrentStep(p => Math.max(0, p - 1)); }} 
             disabled={currentStep === 0}
             className={`flex items-center gap-3 px-6 py-3 rounded-2xl font-black text-[10px] uppercase tracking-[0.2em] transition-all ${currentStep === 0 ? 'text-slate-700 opacity-50 cursor-not-allowed' : 'text-slate-400 hover:text-white hover:bg-slate-800'}`}
           >
             <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M15 19l-7-7 7-7" /></svg>
             Sebelum
           </button>

           <div className="w-[1px] h-6 bg-slate-800"></div>

           <button 
             onClick={() => { window.scrollTo(0,0); setCurrentStep(p => Math.min(STEPS.length - 1, p + 1)); }} 
             disabled={currentStep === STEPS.length - 1}
             className={`flex items-center gap-3 px-10 py-4 rounded-2xl font-black text-[10px] uppercase tracking-[0.2em] transition-all ${currentStep === STEPS.length - 1 ? 'bg-green-500/20 text-green-400' : 'bg-blue-600 text-white hover:bg-blue-500 shadow-xl shadow-blue-900/40'}`}
           >
             {currentStep === STEPS.length - 1 ? 'Lengkap' : 'Seterusnya'}
             {currentStep < STEPS.length - 1 && <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M9 5l7 7-7 7" /></svg>}
           </button>
        </div>
      </footer>
    </div>
  );
}

import React from 'react';
import { OfficerInfo } from './types';

interface Props {
  info: OfficerInfo;
  onChange: (info: Partial<OfficerInfo>) => void;
}

const Step1OfficerInfo: React.FC<Props> = ({ info, onChange }) => {
  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    const val = e.target.type === 'number' ? parseFloat(value) || 0 : value;
    onChange({ [name]: val });
  };

  const SectionHeader = ({ title, subtitle }: { title: string, subtitle: string }) => (
    <div className="mb-10">
      <h3 className="text-2xl font-black text-slate-800 tracking-tighter uppercase">{title}</h3>
      <div className="w-12 h-1.5 bg-blue-600 rounded-full mt-2 mb-3"></div>
      <p className="text-slate-400 text-xs font-bold uppercase tracking-widest">{subtitle}</p>
    </div>
  );

  const InputWrapper = ({ label, children }: { label: string, children: React.ReactNode }) => (
    <div className="space-y-2">
      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">{label}</label>
      {children}
    </div>
  );

  const inputStyles = "w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 focus:bg-white rounded-2xl p-4 outline-none transition-all font-bold text-slate-800 placeholder-slate-200 text-sm";

  return (
    <div className="animate-fadeIn space-y-20">
      {/* Profil Peribadi */}
      <section>
        <SectionHeader title="Profil Peribadi & Kerjaya" subtitle="Lengkapkan maklumat rasmi anda di sini" />
        <div className="grid grid-cols-1 md:grid-cols-2 gap-x-12 gap-y-8">
          <InputWrapper label="Nama Penuh (Huruf Besar)">
            <input name="nama" value={info.nama} onChange={handleChange} className={`${inputStyles} uppercase`} placeholder="CONTOH: AHMAD BIN ALI" />
          </InputWrapper>
          <InputWrapper label="No. Kad Pengenalan">
            <input name="ic" value={info.ic} onChange={handleChange} className={inputStyles} placeholder="000000-00-0000" />
          </InputWrapper>
          <InputWrapper label="Jawatan Semasa">
            <input name="jawatan" value={info.jawatan} onChange={handleChange} className={inputStyles} placeholder="GURU / PEGAWAI TADBIR" />
          </InputWrapper>
          <InputWrapper label="Gred Jawatan">
            <input name="gred" value={info.gred} onChange={handleChange} className={inputStyles} placeholder="S19 / DG41" />
          </InputWrapper>
          <InputWrapper label="Gaji Hakiki (RM)">
            <input type="number" name="gaji" value={info.gaji} onChange={handleChange} className={`${inputStyles} text-right`} />
          </InputWrapper>
          <InputWrapper label="Elaun-elaun (RM)">
            <input type="number" name="elaun" value={info.elaun} onChange={handleChange} className={`${inputStyles} text-right`} />
          </InputWrapper>
        </div>
      </section>

      {/* Perbankan */}
      <section>
        <SectionHeader title="Saluran Pembayaran" subtitle="Maklumat akaun untuk urusan bayaran balik" />
        <div className="grid grid-cols-1 md:grid-cols-2 gap-x-12 gap-y-8">
          <InputWrapper label="Nombor Akaun Bank">
            <input name="akaunBank" value={info.akaunBank} onChange={handleChange} className={inputStyles} />
          </InputWrapper>
          <InputWrapper label="Nama & Alamat Bank">
            <input name="namaBank" value={info.namaBank} onChange={handleChange} className={inputStyles} placeholder="MAYBANK / CIMB" />
          </InputWrapper>
          <InputWrapper label="No. Telefon Bimbit">
            <input name="telefon" value={info.telefon} onChange={handleChange} className={inputStyles} />
          </InputWrapper>
        </div>
      </section>

      {/* Kenderaan */}
      <section>
        <SectionHeader title="Maklumat Kenderaan" subtitle="Kenderaan yang digunakan sepanjang perjalanan" />
        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
          <InputWrapper label="Jenis Kenderaan">
            <select name="kenderaanJenis" value={info.kenderaanJenis} onChange={handleChange} className={`${inputStyles} appearance-none`}>
              <option value="Kereta">Kereta</option>
              <option value="Motosikal">Motosikal</option>
            </select>
          </InputWrapper>
          <InputWrapper label="Model / Jenama">
            <input name="kenderaanModel" value={info.kenderaanModel} onChange={handleChange} className={inputStyles} placeholder="PROTON X50" />
          </InputWrapper>
          <InputWrapper label="Nombor Pendaftaran">
            <input name="noPendaftaran" value={info.noPendaftaran} onChange={handleChange} className={`${inputStyles} uppercase`} placeholder="ABC 1234" />
          </InputWrapper>
        </div>
      </section>

      {/* Alamat */}
      <section>
        <SectionHeader title="Lokasi Rasmi & Kediaman" subtitle="Alamat punca perjalanan" />
        <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
          <InputWrapper label="Alamat Pejabat">
            <textarea name="alamatPejabat" value={info.alamatPejabat} onChange={handleChange} className={`${inputStyles} h-32 resize-none`} />
          </InputWrapper>
          <InputWrapper label="Alamat Rumah Pegawai">
            <textarea name="alamatRumah" value={info.alamatRumah} onChange={handleChange} className={`${inputStyles} h-32 resize-none`} />
          </InputWrapper>
        </div>
      </section>
    </div>
  );
};

