            <div className="bg-blue-600 w-20 h-20 rounded-[2rem] flex items-center justify-center mx-auto mb-6 shadow-2xl shadow-blue-500/40 transform -rotate-3">
              <svg className="w-10 h-10 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15 11a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
            </div>
            <h1 className="text-2xl font-black text-slate-900 tracking-tighter uppercase leading-tight">Tuntutan Perjalanan<br/><span className="text-blue-600">Dalam Negeri</span></h1>
            <p className="text-slate-400 text-[10px] font-black uppercase tracking-[0.2em] mt-3">Portal Pengurusan Tuntutan WP 1.4</p>
          </div>

          <form onSubmit={handleSubmit} className="space-y-6">
            {error && (
              <div className="bg-red-50 text-red-600 p-5 rounded-3xl text-[10px] font-black uppercase tracking-widest border border-red-100 text-center">
                {error}
              </div>
            )}

            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Emel Pengguna</label>
              <input 
                type="email" required value={email} onChange={(e) => setEmail(e.target.value)}
                className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 focus:bg-white rounded-[1.5rem] p-5 outline-none transition-all font-bold text-slate-800"
                placeholder="nama@jabatan.gov.my"
              />
            </div>

            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Kata Laluan</label>
              <input 
                type="password" required value={password} onChange={(e) => setPassword(e.target.value)}
                className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 focus:bg-white rounded-[1.5rem] p-5 outline-none transition-all font-bold text-slate-800"
                placeholder="••••••••"
              />
            </div>

            <button 
              type="submit" disabled={loading}
              className={`w-full py-5 rounded-[1.5rem] font-black text-white shadow-2xl transition-all active:scale-95 flex items-center justify-center gap-3 tracking-[0.1em] ${loading ? 'bg-slate-300' : 'bg-slate-900 hover:bg-slate-800 shadow-slate-900/20'}`}
            >
              {loading ? (
                <div className="w-5 h-5 border-2 border-white/20 border-t-white rounded-full animate-spin"></div>
              ) : isLogin ? 'LOG MASUK SISTEM' : 'DAFTAR AKAUN BARU'}
            </button>
          </form>

          <div className="mt-10 text-center">
            <button 
              onClick={() => setIsLogin(!isLogin)}
              className="text-[10px] font-black text-blue-600 hover:text-blue-700 uppercase tracking-widest transition-colors"
            >
              {isLogin ? 'Tiada Akaun? Daftar Sekarang' : 'Sudah Berdaftar? Log Masuk'}
            </button>
          </div>
        </div>
        <p className="text-center text-slate-600 text-[9px] font-bold uppercase tracking-[0.3em] mt-12">© 2025 Portal Tuntutan WP 1.4 Digital</p>
      </div>
    </div>
  );
}

