import React from 'react';
import { JourneyGroup, JourneyLeg } from './types';

interface Props {
  logs: JourneyGroup[];
  onChange: (logs: JourneyGroup[]) => void;
}

const Step2JourneyLog: React.FC<Props> = ({ logs, onChange }) => {
  const addJourney = () => {
    const newJourney: JourneyGroup = {
      id: Math.random().toString(36).substr(2, 9),
      tarikh: logs.length > 0 ? logs[logs.length - 1].tarikh : '',
      tujuan: '',
      adaBalik: true,
      pergi: { waktuBertolak: '', waktuSampai: '', tempohMinit: 0, dari: 'Pejabat', ke: '', jarak: 0, tol: 0, tolMasuk: '', tolKeluar: '' },
      balik: { waktuBertolak: '', waktuSampai: '', tempohMinit: 0, dari: '', ke: 'Pejabat', jarak: 0, tol: 0, tolMasuk: '', tolKeluar: '' }
    };
    onChange([...logs, newJourney]);
  };

  const calculateArrivalTime = (startTime: string, durationMinutes: number): string => {
    if (!startTime || !durationMinutes) return '';
    const [hours, minutes] = startTime.split(':').map(Number);
    const date = new Date();
    date.setHours(hours);
    date.setMinutes(minutes + durationMinutes);

    const h = date.getHours().toString().padStart(2, '0');
    const m = date.getMinutes().toString().padStart(2, '0');
    return `${h}:${m}`;
  };

  const updateJourney = (id: string, updates: Partial<JourneyGroup>) => {
    onChange(logs.map(j => j.id === id ? { ...j, ...updates } : j));
  };

  const updateLeg = (id: string, legType: 'pergi' | 'balik', field: keyof JourneyLeg, value: any) => {
    onChange(logs.map(j => {
      if (j.id === id) {
        let updatedLeg = { ...j[legType], [field]: value };

        // Logik Auto-Calculate Waktu Sampai
        if (field === 'tempohMinit' || field === 'waktuBertolak') {
          const newArrivalTime = calculateArrivalTime(
            field === 'waktuBertolak' ? value : updatedLeg.waktuBertolak,
            field === 'tempohMinit' ? Number(value) : (updatedLeg.tempohMinit || 0)
          );
          if (newArrivalTime) {
            updatedLeg.waktuSampai = newArrivalTime;
          }
        }

        const updates: any = { [legType]: updatedLeg };

        if (legType === 'pergi' && field === 'ke') {
          updates.balik = { ...j.balik, dari: value };
        }

        return { ...j, ...updates };
      }
      return j;
    }));
  };

  const removeJourney = (id: string) => {
    onChange(logs.filter(j => j.id !== id));
  };

  const totalKm = logs.reduce((sum, j) => sum + j.pergi.jarak + (j.adaBalik ? j.balik.jarak : 0), 0);
  const totalTol = logs.reduce((sum, j) => sum + j.pergi.tol + (j.adaBalik ? j.balik.tol : 0), 0);

  return (
    <div className="animate-fadeIn space-y-8">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-xl font-bold text-slate-900 uppercase tracking-tight">Kenyataan Tuntutan Perjalanan</h2>
          <p className="text-xs text-slate-400 font-medium">Sila masukkan butiran log perjalanan anda secara harian.</p>
        </div>
        <button 
          onClick={addJourney}
          className="bg-slate-900 hover:bg-slate-800 text-white px-5 py-2.5 rounded-lg text-xs font-bold flex items-center gap-2 transition-all active:scale-95 shadow-sm"
        >
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 4v16m8-8H4" /></svg>
          Tambah Log Baru
        </button>
      </div>

      <div className="space-y-6">
        {logs.length === 0 ? (
          <div className="bg-slate-50 border border-slate-200 border-dashed rounded-xl p-16 text-center">
            <p className="text-slate-400 text-sm font-medium">Tiada rekod perjalanan ditambah lagi.</p>
          </div>
        ) : logs.map((journey, idx) => (
          <div key={journey.id} className="bg-white border border-slate-200 rounded-xl overflow-hidden shadow-sm">
            {/* Header */}
            <div className="bg-slate-50/50 px-6 py-4 border-b border-slate-100 flex justify-between items-center">
              <div className="flex items-center gap-4">
                <div className="bg-slate-900 text-white w-6 h-6 rounded flex items-center justify-center text-[10px] font-bold">
                  {idx + 1}
                </div>
                <input 
                  type="date" value={journey.tarikh} 
                  onChange={(e) => updateJourney(journey.id, { tarikh: e.target.value })}
                  className="bg-transparent border-none text-xs font-bold text-slate-700 p-0 focus:ring-0 w-32"
                />
              </div>
              <button 
                onClick={() => removeJourney(journey.id)}
                className="text-slate-300 hover:text-red-500 transition-colors"
              >
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
              </button>
            </div>

            <div className="p-6 space-y-8">
              <div>
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest block mb-2">Tujuan / Urusan Rasmi</label>
                <input 
                  type="text" value={journey.tujuan} 
                  onChange={(e) => updateJourney(journey.id, { tujuan: e.target.value })}
                  className="w-full text-sm font-bold border-b border-slate-100 py-1 focus:ring-0 focus:border-blue-500 outline-none placeholder-slate-200"
                  placeholder="CONTOH: MENGHADIRI MESYUARAT PENGURUSAN DI PUTRAJAYA"
                />
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                {/* Pergi */}
                <div className="space-y-4">
                  <div className="flex items-center gap-2 border-l-2 border-blue-500 pl-3">
                    <span className="text-[10px] font-black text-slate-800 uppercase tracking-widest">Perjalanan Pergi</span>
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1">
                      <label className="text-[9px] font-bold text-slate-400 uppercase">Bertolak</label>
                      <input type="time" value={journey.pergi.waktuBertolak} onChange={(e) => updateLeg(journey.id, 'pergi', 'waktuBertolak', e.target.value)} className="w-full border border-slate-200 rounded-lg p-2 text-xs font-medium" />
                    </div>
                    <div className="space-y-1">
                      <label className="text-[9px] font-bold text-slate-400 uppercase">Tempoh (Minit)</label>
                      <input type="number" value={journey.pergi.tempohMinit || ''} onChange={(e) => updateLeg(journey.id, 'pergi', 'tempohMinit', parseInt(e.target.value) || 0)} className="w-full border border-slate-200 rounded-lg p-2 text-xs font-bold text-blue-600 bg-blue-50/30" placeholder="Minit" />
                    </div>
                  </div>
                  <div className="space-y-1">
                    <label className="text-[9px] font-bold text-slate-400 uppercase">Waktu Sampai (Auto)</label>
