                  </div>
                  <div className="flex items-center gap-2 bg-slate-50 p-2 rounded-lg border border-slate-100">
                    <input type="text" value={journey.pergi.dari} onChange={(e) => updateLeg(journey.id, 'pergi', 'dari', e.target.value)} placeholder="Dari" className="w-1/2 bg-transparent text-[11px] font-bold outline-none" />
                    <span className="text-slate-300">→</span>
                    <input type="text" value={journey.pergi.ke} onChange={(e) => updateLeg(journey.id, 'pergi', 'ke', e.target.value)} placeholder="Ke" className="w-1/2 bg-transparent text-[11px] font-bold outline-none" />
                  </div>

                  {/* Butiran Tol */}
