                    <div className="grid grid-cols-2 gap-2">
                      <input type="text" value={journey.pergi.tolMasuk || ''} onChange={(e) => updateLeg(journey.id, 'pergi', 'tolMasuk', e.target.value)} placeholder="Tol Masuk" className="border border-slate-200 rounded-lg p-2 text-[10px] uppercase font-bold" />
                      <input type="text" value={journey.pergi.tolKeluar || ''} onChange={(e) => updateLeg(journey.id, 'pergi', 'tolKeluar', e.target.value)} placeholder="Tol Keluar" className="border border-slate-200 rounded-lg p-2 text-[10px] uppercase font-bold" />
                    </div>
                    <div className="flex gap-2">
                       <input type="number" step="0.01" value={journey.pergi.tol} onChange={(e) => updateLeg(journey.id, 'pergi', 'tol', parseFloat(e.target.value) || 0)} placeholder="Jumlah Tol (RM)" className="w-1/2 border border-slate-200 rounded-lg p-2 text-xs text-right font-bold text-blue-700" />
                       <input type="number" step="0.1" value={journey.pergi.jarak} onChange={(e) => updateLeg(journey.id, 'pergi', 'jarak', parseFloat(e.target.value) || 0)} placeholder="Jarak (KM)" className="w-1/2 border border-slate-200 rounded-lg p-2 text-xs text-right font-black" />
                    </div>
                  </div>
                </div>

                {/* Balik */}
                <div className="space-y-4">
                  <div className="flex items-center justify-between border-l-2 border-amber-500 pl-3">
